  BLOOD_GROUP_OPTIONS,
  GENDER_OPTIONS,
  MARITAL_STATUS_OPTIONS,
  NATIONALITY_OPTIONS,
  PAYMENT_TYPE_OPTIONS,
} from '@/features/patients/patientOptions';
import {
  patientFormSchema,
  type PatientFormValues,
} from '@/features/patients/schemas/patientForm.schema';
import type { PatientWire } from '@/features/patients/types/patient.types';
import { ApiError } from '@/lib/apiClient';

type PatientFormProps =
  | { mode: 'create' }
  | { mode: 'edit'; patientId: string; initialData: PatientWire };

export function PatientForm(props: Readonly<PatientFormProps>) {
  const navigate = useNavigate();
  const isEdit = props.mode === 'edit';

  const createPatient = useCreatePatient();
  // Needs an id up front (hooks can't be conditional); only ever invoked from
  // the edit branch, so '' in create mode is inert.
  const updatePatient = useUpdatePatient(isEdit ? props.patientId : '');

  const form = useForm<PatientFormValues>({
    resolver: zodResolver(patientFormSchema),
    mode: 'onTouched',
    reValidateMode: 'onChange',
    defaultValues: isEdit
      ? toPatientFormValues(props.initialData)
      : emptyPatientFormValues(),
  });

  async function onSubmit(values: PatientFormValues) {
    try {
      if (props.mode === 'create') {
        await createPatient.mutateAsync(buildCreatePatientBody(values));
      } else {
        const body = buildUpdatePatientBody(values, form.formState.dirtyFields);
        if (Object.keys(body).length === 0) {
          navigate('/patients');
          return;
        }
        await updatePatient.mutateAsync(body);
      }
      // DEVIATION: the house convention is inline surfaces, not toasts (see
      // PatientListError.tsx). A success toast on form submit is a deliberate,
      // approved exception; submit *failures* stay inline in the Alert below.
      toast.success(
        props.mode === 'create' ? 'Patient registered.' : 'Patient updated.',
      );
      navigate('/patients');
    } catch (err) {
      form.setError('root', {
        message:
          err instanceof ApiError
            ? err.apiMessage
            : 'Something went wrong. Please try again.',
      });
    }
  }

  return (
    <Form {...form}>
      <form
        className="flex flex-col gap-6"
        onSubmit={form.handleSubmit(onSubmit)}
        noValidate
      >
        {form.formState.errors.root?.message && (
          <Alert variant="destructive" role="alert">
            {form.formState.errors.root.message}
          </Alert>
        )}

        <PatientFormSection
          title="Identity"
          description="Legal name, date of birth and gender."
        >
          <PatientTextField
            control={form.control}
            name="firstName"
            label="First name"
            autoComplete="given-name"
            required
          />
          <PatientTextField
            control={form.control}
            name="lastName"
            label="Last name"
            autoComplete="family-name"
            required
          />
          <PatientTextField
            control={form.control}
            name="middleName"
            label="Middle name"
            autoComplete="additional-name"
          />
          <PatientTextField
            control={form.control}
            name="dateOfBirth"
            label="Date of birth"
            type="date"
            required
          />
          <PatientSelectField
            control={form.control}
            name="gender"
            label="Gender"
            options={GENDER_OPTIONS}
            placeholder="Select a gender"
            required
          />
        </PatientFormSection>

        <PatientFormSection
          title="Contact"
          description="How the clinic reaches this patient."
        >
          <PatientTextField
            control={form.control}
            name="phoneNumber"
            label="Phone number"
            type="tel"
            autoComplete="tel"
            required
          />
          <PatientTextField
            control={form.control}
            name="email"
            label="Email"
            type="email"
            autoComplete="email"
          />
          <PatientTextareaField
            control={form.control}
            name="address"
            label="Residential address"
            className="sm:col-span-2"
          />
        </PatientFormSection>

        <PatientFormSection
          title="Demographics"
          description="Optional background details."
        >
          <PatientSelectField
            control={form.control}
            name="bloodGroup"
            label="Blood group"
            options={BLOOD_GROUP_OPTIONS}
            placeholder="Select a blood group"
          />
          <PatientSelectField
            control={form.control}
            name="maritalStatus"
            label="Marital status"
            options={MARITAL_STATUS_OPTIONS}
            placeholder="Select a marital status"
          />
          <PatientComboboxField
            control={form.control}
            name="nationality"
            label="Nationality"
            options={NATIONALITY_OPTIONS}
            placeholder="Select nationality"
          />
          <PatientTextField
            control={form.control}
            name="occupation"
            label="Occupation"
          />
        </PatientFormSection>

        <PatientFormSection
          title="Payment"
          description="Determines how visits are billed."
        >
          <PatientSelectField
            control={form.control}
            name="paymentType"
            label="Payment type"
            options={PAYMENT_TYPE_OPTIONS}
            placeholder="Select a payment type"
            required
          />
        </PatientFormSection>

        <PatientFormSection
          title="Next of kin"
          description="Emergency contact for this patient."
        >
          <PatientTextField
            control={form.control}
            name="nextOfKin.name"
            label="Full name"
            required
          />
          <PatientTextField
            control={form.control}
            name="nextOfKin.phone"
            label="Phone number"
            type="tel"
            required
          />
          <PatientTextField
            control={form.control}
            name="nextOfKin.relationship"
            label="Relationship"
            required
          />
          <PatientTextareaField
            control={form.control}
            name="nextOfKin.address"
            label="Address"
            className="sm:col-span-2"
            required
          />
        </PatientFormSection>

        {isEdit && (
          <PatientFormSection
            title="Status"
            description="Inactive patients stay on record but are filtered out by default."
          >
            <FormField
              control={form.control}
              name="isActive"
              render={({ field }) => (
                <FormItem className="flex flex-row items-center gap-2 sm:col-span-2">
                  <FormControl>
                    <Checkbox
                      checked={field.value}
                      onCheckedChange={(v) => field.onChange(v === true)}
                    />
                  </FormControl>
                  <FormLabel>Active patient</FormLabel>
                </FormItem>
              )}
            />
          </PatientFormSection>
        )}

        <div className="sticky bottom-0 z-10 -mx-6 flex items-center gap-3 border-t bg-background/80 px-6 py-4 backdrop-blur">
          <Button
            type="submit"
            disabled={
              form.formState.isSubmitting || (isEdit && !form.formState.isDirty)
            }
          >
            {form.formState.isSubmitting
              ? 'Saving…'
              : isEdit
                ? 'Save changes'
                : 'Register patient'}
          </Button>
          <Button type="button" variant="outline" asChild>
            <Link to="/patients">Cancel</Link>
          </Button>
        </div>
      </form>
    </Form>
  );
}

import { ArrowDown, ArrowUp, ChevronsUpDown } from 'lucide-react';
import type { TableMeta } from '@tanstack/react-table';

import { cn } from '@/lib/utils';
import type { Patient } from '@/features/patients/types/patient.types';

// Byte-identical to the previous inline sortable-header button
// (PatientTable.tsx:80). Do not retype — copied verbatim.
const HEADER_BUTTON =
  '-mx-1 inline-flex items-center gap-1 rounded-sm px-1 py-0.5 text-xs font-medium tracking-wide text-muted-foreground uppercase transition-colors motion-reduce:transition-none hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring';

interface PatientSortableHeaderProps {
  readonly label: string;
  readonly sortKey: 'name' | 'age';
  readonly align?: 'start' | 'end';
  readonly meta: TableMeta<Patient>;
}

/**
 * The in-`<th>` sort toggle button. Visually identical to a plain header apart
 * from the trailing sort icon. `aria-sort` is deliberately NOT set here — it
 * belongs on the `<th>` (see PatientTable). `align="end"` reverses the flex row
 * so the icon sits left of the label in a right-aligned numeric column.
 */
export function PatientSortableHeader({
  label,
  sortKey,
  align,
  meta,
}: PatientSortableHeaderProps) {
  const active = meta.sortField === sortKey;
  const dir = meta.sortDir;

  return (
    <button
      type="button"
      onClick={() => meta.onToggleSort(sortKey)}
      aria-label={
        active
          ? `Sort by ${label.toLowerCase()}, currently ${
              dir === 'asc' ? 'ascending' : 'descending'
            }`
          : `Sort by ${label.toLowerCase()}`
      }
      className={cn(HEADER_BUTTON, align === 'end' && 'flex-row-reverse')}
    >
      {label}
      {!active ? (
        <ChevronsUpDown
          aria-hidden="true"
          className="size-3.5 text-muted-foreground/60"
        />
      ) : dir === 'asc' ? (
        <ArrowUp aria-hidden="true" className="size-3.5" />
      ) : (
        <ArrowDown aria-hidden="true" className="size-3.5" />
      )}
    </button>
  );
}

import { useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import {
  Activity,
  CalendarClock,
  FileText,
  Pencil,
  Receipt,
